def fill_phone_normalized(apps, schema_editor):
    """Store existing phone numbers in +92 format (same rule as the app)."""
    Inquiry = apps.get_model("inquiries", "Inquiry")
    for inquiry in Inquiry.objects.all():
        digits = re.sub(r"\D", "", inquiry.phone or "")
        if digits.startswith("0092"):
            digits = digits[2:]
        elif digits.startswith("0"):
            digits = "92" + digits[1:]
        inquiry.phone_normalized = "+" + digits if digits else ""
        inquiry.save(update_fields=["phone_normalized"])


